/**
 * Sub-components for AdminAccreditationQueue: SubmissionRow, SubmissionDetail, ReviewForm.
 */

import type { AccreditationQueueItem } from '../../types/accreditation';
import type { AdminAccreditationSubmissionDetail } from '../../types/accreditation';
import {
  accreditationStatusBadgeClass,
  formatAccreditationDate,
  labelAccreditationMethod,
} from './AdminAccreditationQueueHelpers';

// =============================================================================
// SubmissionRow
// =============================================================================

export interface SubmissionRowProps {
  item: AccreditationQueueItem;
  isExpanded: boolean;
  detail: AdminAccreditationSubmissionDetail | null;
  detailLoading: boolean;
  detailError: string | null;
  reviewNotes: string;
  rejectionReason: string;
  isReviewing: boolean;
  reviewError: string | null;
  onRowClick: (id: string) => void;
  onDocumentDownload: (docId: string) => void;
  onReviewNotesChange: (v: string) => void;
  onRejectionReasonChange: (v: string) => void;
  onReview: (id: string, approved: boolean) => void;
}

export function SubmissionRow({
  item,
  isExpanded,
  detail,
  detailLoading,
  detailError,
  reviewNotes,
  rejectionReason,
  isReviewing,
  reviewError,
  onRowClick,
  onDocumentDownload,
  onReviewNotesChange,
  onRejectionReasonChange,
  onReview,
}: SubmissionRowProps) {
  const amountDisplay =
    item.statedAmountUsd !== undefined
      ? `$${item.statedAmountUsd.toLocaleString()}`
      : item.investmentCommitmentUsd !== undefined
        ? `$${item.investmentCommitmentUsd.toLocaleString()}`
        : '—';

  return (
    <>
      <div
        className={`cedros-admin-list-row cedros-admin-list-row--clickable ${isExpanded ? 'cedros-admin-list-row--expanded' : ''}`}
        role="row"
        onClick={() => onRowClick(item.id)}
        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onRowClick(item.id); } }}
        tabIndex={0}
        aria-expanded={isExpanded}
      >
        <div className="cedros-admin-list-td" role="cell">
          {item.userEmail ?? <span className="cedros-admin-list-td-mono">{item.userId.slice(0, 12)}...</span>}
        </div>
        <div className="cedros-admin-list-td" role="cell">
          {labelAccreditationMethod(item.method)}
        </div>
        <div className="cedros-admin-list-td" role="cell">{amountDisplay}</div>
        <div className="cedros-admin-list-td" role="cell">
          {formatAccreditationDate(item.createdAt)}
        </div>
        <div className="cedros-admin-list-td" role="cell">
          <span className={`cedros-admin-badge ${accreditationStatusBadgeClass(item.status)}`}>
            {item.status}
          </span>
        </div>
      </div>

      {isExpanded && (
        <div className="cedros-admin-accreditation-queue__detail" role="region" aria-label="Submission detail">
          {detailLoading && (
            <div className="cedros-admin-accreditation-queue__detail-loading">
              <span className="cedros-admin-loading-indicator" />
              <span className="cedros-admin-loading-text">Loading detail...</span>
            </div>
          )}
          {detailError && <p className="cedros-admin-error">{detailError}</p>}
          {detail && (
            <>
              <SubmissionDetail detail={detail} onDocumentDownload={onDocumentDownload} />

              {item.status === 'pending' && (
                <ReviewForm
                  submissionId={item.id}
                  notes={reviewNotes}
                  rejectionReason={rejectionReason}
                  isReviewing={isReviewing}
                  error={reviewError}
                  onNotesChange={onReviewNotesChange}
                  onRejectionReasonChange={onRejectionReasonChange}
                  onReview={onReview}
                />
              )}
            </>
          )}
        </div>
      )}
    </>
  );
}

// =============================================================================
// SubmissionDetail
// =============================================================================

interface SubmissionDetailProps {
  detail: AdminAccreditationSubmissionDetail;
  onDocumentDownload: (docId: string) => void;
}

function SubmissionDetail({ detail, onDocumentDownload }: SubmissionDetailProps) {
  return (
    <div className="cedros-admin-accreditation-queue__detail-fields">
      {detail.incomeType && (
        <div className="cedros-admin-detail-row">
          <span className="cedros-admin-detail-label">Income Type</span>
          <span className="cedros-admin-detail-value">{detail.incomeType}</span>
        </div>
      )}
      {detail.statedAmountUsd !== undefined && (
        <div className="cedros-admin-detail-row">
          <span className="cedros-admin-detail-label">Stated Amount</span>
          <span className="cedros-admin-detail-value">${detail.statedAmountUsd.toLocaleString()}</span>
        </div>
      )}
      {detail.crdNumber && (
        <div className="cedros-admin-detail-row">
          <span className="cedros-admin-detail-label">CRD Number</span>
          <span className="cedros-admin-detail-value cedros-admin-list-td-mono">{detail.crdNumber}</span>
        </div>
      )}
      {detail.licenseType && (
        <div className="cedros-admin-detail-row">
          <span className="cedros-admin-detail-label">License Type</span>
          <span className="cedros-admin-detail-value">{detail.licenseType}</span>
        </div>
      )}
      {detail.investmentCommitmentUsd !== undefined && (
        <div className="cedros-admin-detail-row">
          <span className="cedros-admin-detail-label">Investment Commitment</span>
          <span className="cedros-admin-detail-value">${detail.investmentCommitmentUsd.toLocaleString()}</span>
        </div>
      )}
      {detail.entityType && (
        <div className="cedros-admin-detail-row">
          <span className="cedros-admin-detail-label">Entity Type</span>
          <span className="cedros-admin-detail-value">{detail.entityType}</span>
        </div>
      )}
      {detail.userStatement && (
        <div className="cedros-admin-detail-row cedros-admin-detail-row--block">
          <span className="cedros-admin-detail-label">User Statement</span>
          <p className="cedros-admin-detail-statement">{detail.userStatement}</p>
        </div>
      )}

      {detail.documents.length > 0 && (
        <div className="cedros-admin-accreditation-queue__documents">
          <h4 className="cedros-admin-accreditation-queue__documents-title">Documents</h4>
          {detail.documents.map((doc) => (
            <div key={doc.id} className="cedros-admin-accreditation-queue__document-row">
              <span className="cedros-admin-accreditation-queue__document-name">
                {doc.originalFilename ?? doc.documentType}
              </span>
              {doc.fileSizeBytes && (
                <span className="cedros-admin-list-td-muted">
                  {(doc.fileSizeBytes / 1024).toFixed(1)} KB
                </span>
              )}
              <button
                type="button"
                className="cedros-button cedros-button-outline cedros-button-sm"
                onClick={() => onDocumentDownload(doc.id)}
              >
                Download
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// =============================================================================
// ReviewForm
// =============================================================================

interface ReviewFormProps {
  submissionId: string;
  notes: string;
  rejectionReason: string;
  isReviewing: boolean;
  error: string | null;
  onNotesChange: (v: string) => void;
  onRejectionReasonChange: (v: string) => void;
  onReview: (id: string, approved: boolean) => void;
}

function ReviewForm({
  submissionId,
  notes,
  rejectionReason,
  isReviewing,
  error,
  onNotesChange,
  onRejectionReasonChange,
  onReview,
}: ReviewFormProps) {
  return (
    <div className="cedros-admin-accreditation-queue__review-form">
      <h4 className="cedros-admin-accreditation-queue__review-title">Review Decision</h4>

      <div className="cedros-admin-form-row">
        <label className="cedros-admin-form-label" htmlFor="review-notes">
          Reviewer Notes (internal)
        </label>
        <textarea
          id="review-notes"
          className="cedros-admin-form-textarea"
          value={notes}
          onChange={(e) => onNotesChange(e.target.value)}
          rows={2}
          placeholder="Optional internal notes"
        />
      </div>

      <div className="cedros-admin-form-row">
        <label className="cedros-admin-form-label" htmlFor="rejection-reason">
          Rejection Reason (required if rejecting)
        </label>
        <textarea
          id="rejection-reason"
          className="cedros-admin-form-textarea"
          value={rejectionReason}
          onChange={(e) => onRejectionReasonChange(e.target.value)}
          rows={2}
          placeholder="Reason shown to user"
        />
      </div>

      {error && <p className="cedros-admin-error">{error}</p>}

      <div className="cedros-admin-accreditation-queue__review-actions">
        <button
          type="button"
          className="cedros-button cedros-button-primary cedros-button-sm"
          onClick={() => onReview(submissionId, true)}
          disabled={isReviewing}
          aria-busy={isReviewing}
        >
          {isReviewing ? 'Saving...' : 'Approve'}
        </button>
        <button
          type="button"
          className="cedros-button cedros-button-danger cedros-button-sm"
          onClick={() => onReview(submissionId, false)}
          disabled={isReviewing}
          aria-busy={isReviewing}
        >
          {isReviewing ? 'Saving...' : 'Reject'}
        </button>
      </div>
    </div>
  );
}
