/**
 * Admin queue for reviewing accredited investor submissions.
 *
 * Tabs: Pending | All
 * Each row is expandable to show submission detail, documents, and the
 * approve/reject review form.
 *
 * Requires system admin privileges.
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useCedrosLoginAdminClientContext } from '../../hooks/useCedrosLoginAdminClientContext';
import { AdminUserApiClient } from '../../utils/adminUserApi';
import type { AccreditationQueueItem } from '../../types/accreditation';
import type { AdminAccreditationSubmissionDetail } from '../../types/accreditation';
import { SubmissionRow } from './AdminAccreditationQueueRows';

// =============================================================================
// Props
// =============================================================================

export interface AdminAccreditationQueueProps {
  className?: string;
}

type TabId = 'pending' | 'all';

const PAGE_SIZE = 20;

// =============================================================================
// Component
// =============================================================================

/**
 * Admin accreditation review queue.
 *
 * Inputs: className.
 * Outputs: renders tabbed queue; approves/rejects submissions via API.
 * Errors: displayed inline per row and globally.
 */
export function AdminAccreditationQueue({ className = '' }: AdminAccreditationQueueProps) {
  const { config, _internal } = useCedrosLoginAdminClientContext();

  const apiClient = useMemo(
    () =>
      new AdminUserApiClient(
        config.serverUrl,
        config.requestTimeout,
        config.retryAttempts,
        _internal?.getAccessToken
      ),
    [config.serverUrl, config.requestTimeout, config.retryAttempts, _internal]
  );

  const [activeTab, setActiveTab] = useState<TabId>('pending');
  const [items, setItems] = useState<AccreditationQueueItem[]>([]);
  const [total, setTotal] = useState(0);
  const [offset, setOffset] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);

  // Expanded row state
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [detail, setDetail] = useState<AdminAccreditationSubmissionDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [detailError, setDetailError] = useState<string | null>(null);

  // Review form state
  const [reviewNotes, setReviewNotes] = useState('');
  const [rejectionReason, setRejectionReason] = useState('');
  const [isReviewing, setIsReviewing] = useState(false);
  const [reviewError, setReviewError] = useState<string | null>(null);
  const [reviewSuccess, setReviewSuccess] = useState<string | null>(null);

  const fetchItems = useCallback(async () => {
    setIsLoading(true);
    setFetchError(null);
    try {
      const resp = await apiClient.listPendingAccreditations(PAGE_SIZE, offset);
      setItems(resp.items);
      setTotal(resp.total);
    } catch (err) {
      setFetchError(err instanceof Error ? err.message : 'Failed to load submissions');
    } finally {
      setIsLoading(false);
    }
  }, [apiClient, offset]);

  useEffect(() => {
    fetchItems();
  }, [fetchItems]);

  // Reset offset when tab changes
  useEffect(() => {
    setOffset(0);
    setExpandedId(null);
    setDetail(null);
  }, [activeTab]);

  const handleRowClick = useCallback(
    async (id: string) => {
      if (expandedId === id) {
        setExpandedId(null);
        setDetail(null);
        return;
      }
      setExpandedId(id);
      setDetail(null);
      setDetailError(null);
      setReviewNotes('');
      setRejectionReason('');
      setReviewError(null);
      setReviewSuccess(null);
      setDetailLoading(true);
      try {
        const d = await apiClient.getAccreditationSubmission(id);
        setDetail(d);
      } catch (err) {
        setDetailError(err instanceof Error ? err.message : 'Failed to load submission detail');
      } finally {
        setDetailLoading(false);
      }
    },
    [expandedId, apiClient]
  );

  const handleDocumentDownload = useCallback(
    async (docId: string) => {
      try {
        const url = await apiClient.getAccreditationDocumentUrl(docId);
        window.open(url, '_blank', 'noopener,noreferrer');
      } catch (err) {
        setReviewError(err instanceof Error ? err.message : 'Failed to get document URL');
      }
    },
    [apiClient]
  );

  const handleReview = useCallback(
    async (submissionId: string, approved: boolean) => {
      if (!approved && !rejectionReason.trim()) {
        setReviewError('Rejection reason is required.');
        return;
      }
      setIsReviewing(true);
      setReviewError(null);
      setReviewSuccess(null);
      try {
        await apiClient.reviewAccreditation(
          submissionId,
          approved,
          reviewNotes.trim() || undefined,
          approved ? undefined : rejectionReason.trim()
        );
        setReviewSuccess(approved ? 'Submission approved.' : 'Submission rejected.');
        setExpandedId(null);
        setDetail(null);
        fetchItems();
      } catch (err) {
        setReviewError(err instanceof Error ? err.message : 'Failed to submit review');
      } finally {
        setIsReviewing(false);
      }
    },
    [apiClient, reviewNotes, rejectionReason, fetchItems]
  );

  const totalPages = Math.ceil(total / PAGE_SIZE);
  const currentPage = Math.floor(offset / PAGE_SIZE) + 1;

  const pendingCount = activeTab === 'pending' ? total : items.filter((i) => i.status === 'pending').length;

  return (
    <div className={`cedros-admin-accreditation-queue ${className}`}>
      <div className="cedros-admin-accreditation-queue__header">
        <h2 className="cedros-admin-accreditation-queue__title">
          Accreditation Review Queue
          {pendingCount > 0 && (
            <span className="cedros-admin-queue-count" aria-label={`${pendingCount} pending`}>
              {pendingCount}
            </span>
          )}
        </h2>
        <button
          type="button"
          className="cedros-admin__stats-bar-refresh"
          onClick={fetchItems}
          disabled={isLoading}
          title="Refresh"
          aria-label="Refresh list"
        >
          {isLoading ? '...' : '↻'}
        </button>
      </div>

      <div className="cedros-admin-tabs cedros-admin-tabs--line" role="tablist">
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'pending' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => setActiveTab('pending')}
          aria-selected={activeTab === 'pending'}
          role="tab"
        >
          Pending
        </button>
        <button
          type="button"
          className={`cedros-admin-tab ${activeTab === 'all' ? 'cedros-admin-tab-active' : ''}`}
          onClick={() => setActiveTab('all')}
          aria-selected={activeTab === 'all'}
          role="tab"
        >
          All
        </button>
      </div>

      {reviewSuccess && (
        <div className="cedros-admin-accreditation-queue__result cedros-admin-accreditation-queue__result--success">
          {reviewSuccess}
        </div>
      )}

      {fetchError && (
        <div className="cedros-admin-accreditation-queue cedros-admin-accreditation-queue--error">
          <p className="cedros-admin-error">{fetchError}</p>
          <button type="button" className="cedros-button cedros-button-outline cedros-button-sm" onClick={fetchItems}>
            Retry
          </button>
        </div>
      )}

      {!fetchError && isLoading && items.length === 0 ? (
        <div className="cedros-admin-accreditation-queue--loading">
          <span className="cedros-admin-loading-indicator" />
          <span className="cedros-admin-loading-text">Loading submissions...</span>
        </div>
      ) : (
        <div role="tabpanel">
          {items.length === 0 ? (
            <div className="cedros-admin-empty-message">No submissions found.</div>
          ) : (
            <>
              <div className="cedros-admin-list-table" role="table" aria-label="Accreditation submissions">
                <div className="cedros-admin-list-thead" role="row">
                  <div className="cedros-admin-list-th" role="columnheader">User</div>
                  <div className="cedros-admin-list-th" role="columnheader">Method</div>
                  <div className="cedros-admin-list-th" role="columnheader">Amount</div>
                  <div className="cedros-admin-list-th" role="columnheader">Submitted</div>
                  <div className="cedros-admin-list-th" role="columnheader">Status</div>
                </div>
                {items.map((item) => (
                  <SubmissionRow
                    key={item.id}
                    item={item}
                    isExpanded={expandedId === item.id}
                    detail={expandedId === item.id ? detail : null}
                    detailLoading={expandedId === item.id && detailLoading}
                    detailError={expandedId === item.id ? detailError : null}
                    reviewNotes={reviewNotes}
                    rejectionReason={rejectionReason}
                    isReviewing={isReviewing}
                    reviewError={expandedId === item.id ? reviewError : null}
                    onRowClick={handleRowClick}
                    onDocumentDownload={handleDocumentDownload}
                    onReviewNotesChange={setReviewNotes}
                    onRejectionReasonChange={setRejectionReason}
                    onReview={handleReview}
                  />
                ))}
              </div>

              {totalPages > 1 && (
                <div className="cedros-admin-pagination">
                  <button
                    type="button"
                    className="cedros-button cedros-button-outline cedros-button-sm"
                    onClick={() => setOffset(Math.max(0, offset - PAGE_SIZE))}
                    disabled={currentPage <= 1}
                  >
                    Previous
                  </button>
                  <span className="cedros-admin-page-info">
                    Page {currentPage} of {totalPages} ({total} total)
                  </span>
                  <button
                    type="button"
                    className="cedros-button cedros-button-outline cedros-button-sm"
                    onClick={() => setOffset(offset + PAGE_SIZE)}
                    disabled={currentPage >= totalPages}
                  >
                    Next
                  </button>
                </div>
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
}
